<script setup>
import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import PageHeader from'../../Components/PageHeader.vue';import UiAlert from'../../Components/UiAlert.vue';import UiButton from'../../Components/UiButton.vue';import UiCard from'../../Components/UiCard.vue';import UiModal from'../../Components/UiModal.vue';import{Head,Link,useForm,router}from'@inertiajs/vue3';import{onBeforeUnmount,ref,watch}from'vue';
const p=defineProps({group:Object,cover:Object,section:String,counts:Object});const initial={...p.group,event_type:p.group.event_type||'event',anonymous_access_mode:p.group.anonymous_access_mode||'disabled',invitation_expires_at:p.group.invitation_expires_at?.slice?.(0,16)||null,event_code_expires_at:p.group.event_code_expires_at?.slice?.(0,16)||null};const form=useForm(initial),favouriteForm=useForm({favourites_enabled:p.group.favourites_enabled}),coverForm=useForm({cover_photo:null}),coverPreview=ref(null),coverInput=ref(null),confirmRemove=ref(false);const tabs=[['general','General Settings'],['participants','Participants'],['privacy','Privacy Settings'],['folders','Folders'],['design','Design'],['downloads','View & Download'],['branding','Branding & Sponsors'],['favourites','Client Favourites']];const fields={general:['name','description','event_type','event_date','location','membership_status','membership_limit','is_active'],privacy:['privacy','anyone_with_link_can_join','anonymous_access_mode','allow_guest_upload','participants_can_edit_identity','face_recognition_enabled','invitation_expires_at','event_code_expires_at'],downloads:['downloads_enabled','watermark_enabled'],branding:['watermark_enabled','watermark_text']};const save=()=>form.transform(data=>Object.fromEntries([['_method','PUT'],...(fields[p.section]||[]).map(key=>[key,key==='event_date'&&data[key]?.slice?data[key].slice(0,10):data[key]])])).post(`/groups/${p.group.id}`,{forceFormData:true,preserveScroll:true});function clearCover(){if(coverPreview.value)URL.revokeObjectURL(coverPreview.value);coverPreview.value=null;coverForm.cover_photo=null;if(coverInput.value)coverInput.value.value=''}function chooseCover(e){const file=e.target.files?.[0];if(!file)return;if(coverPreview.value)URL.revokeObjectURL(coverPreview.value);coverPreview.value=null;coverForm.cover_photo=file;coverPreview.value=URL.createObjectURL(file)}function uploadCover(){coverForm.post(`/groups/${p.group.id}/cover`,{forceFormData:true,preserveScroll:true,onSuccess:()=>{clearCover();router.reload({only:['cover'],preserveScroll:true})}})}function removeCover(){router.delete(`/groups/${p.group.id}/cover`,{preserveScroll:true,onSuccess:()=>router.reload({only:['cover'],preserveScroll:true}),onFinish:()=>confirmRemove.value=false})}let poll=null;watch(()=>p.cover?.state,state=>{if(poll){clearInterval(poll);poll=null}if(['queued','processing'].includes(state))poll=setInterval(()=>router.reload({only:['cover'],preserveScroll:true,preserveState:true}),2000)},{immediate:true});onBeforeUnmount(()=>{clearCover();if(poll)clearInterval(poll)});
</script>
<template><AppShell><Head title="Group Settings"/><GroupNav :group="group"/><div class="lp-page mt-6"><PageHeader eyebrow="Group Settings" :title="group.name" description="Every supported section has a direct, refresh-safe URL."/><div class="mt-6 grid gap-6 lg:grid-cols-[240px_1fr]"><nav class="lp-card h-fit p-2" aria-label="Group settings sections"><Link v-for="tab in tabs" :key="tab[0]" :href="`/groups/${group.id}/settings/${tab[0]}`" :class="['block rounded-xl px-4 py-3 text-sm font-semibold',section===tab[0]?'bg-indigo/10 text-indigo':'text-slate-600 hover:bg-slate-50']">{{tab[1]}}</Link></nav><UiCard>
<div v-if="section==='participants'"><h2 class="text-xl font-bold">Participants</h2><p class="lp-subtitle">{{counts.participants}} people currently belong to this Group.</p><UiButton :href="`/groups/${group.id}/members`" class="mt-6">Manage participants</UiButton></div>
<div v-else-if="section==='folders'"><h2 class="text-xl font-bold">Folders</h2><p class="lp-subtitle">{{counts.folders}} folders organize this Group gallery.</p><UiButton :href="`/groups/${group.id}/folders`" class="mt-6">Manage folders</UiButton></div>
<form v-else-if="section==='favourites'" class="space-y-5" @submit.prevent="favouriteForm.put(`/groups/${group.id}`,{preserveScroll:true})"><h2 class="text-xl font-bold">Favourites</h2><p class="lp-subtitle">{{counts.favorites}} accessible photographs currently have favourites.</p><label class="flex gap-3 text-sm"><input v-model="favouriteForm.favourites_enabled" type="checkbox" class="accent-indigo">Allow authorized viewers to add photos to their favourites</label><UiButton type="submit" :loading="favouriteForm.processing">Save favourite settings</UiButton><UiButton :href="`/groups/${group.id}/favorites`" variant="secondary">View my favourites</UiButton></form>
<div v-else-if="section==='design'"><h2 class="text-xl font-bold">Design</h2><UiAlert class="mt-5">Group themes and gallery-presentation values are not supported by the current backend. No mock controls are shown.</UiAlert></div>
<form v-else class="space-y-5" @submit.prevent="save"><template v-if="section==='general'"><h2 class="text-xl font-bold">General Settings</h2><section class="space-y-4 border-b border-slate-200 pb-6"><div><h3 class="font-semibold">Group cover photo</h3><p class="lp-help">Private JPG, PNG or WebP · maximum 10 MB · minimum 800×300</p></div><div class="h-[140px] overflow-hidden bg-gradient-to-br from-ink via-indigo to-coral/70 md:h-[180px]"><img v-if="coverPreview||cover.url" :key="coverPreview||cover.asset_uuid" :src="coverPreview||cover.url" :alt="'Cover photo for ' + group.name" class="h-full w-full object-cover object-center"><div v-else class="flex h-full items-center justify-center text-4xl font-bold text-white">{{group.name.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase()}}</div></div><UiAlert v-if="['queued','processing'].includes(cover.state)">The new cover is processing. The existing cover remains visible until processing succeeds.</UiAlert><UiAlert v-if="cover.state==='failed'" tone="error">{{cover.error}}</UiAlert><input ref="coverInput" type="file" accept="image/jpeg,image/png,image/webp" class="block w-full text-sm" @change="chooseCover"><span v-if="coverForm.errors.cover_photo" class="lp-error">{{coverForm.errors.cover_photo}}</span><div v-if="coverForm.progress" class="h-2 overflow-hidden rounded-full bg-slate-200"><div class="h-full bg-indigo" :style="{width: coverForm.progress.percentage + '%'}"></div></div><div class="flex flex-wrap gap-3"><UiButton type="button" :disabled="!coverForm.cover_photo" :loading="coverForm.processing" @click="uploadCover">{{cover.url?'Replace cover':'Upload cover'}}</UiButton><UiButton v-if="cover.state==='failed'" type="button" variant="secondary" @click="router.post('/groups/' + group.id + '/cover/retry')">Retry processing</UiButton><UiButton v-if="cover.url||cover.state!=='empty'" type="button" variant="danger" @click="confirmRemove=true">Remove cover</UiButton></div></section><label class="lp-label">Group name<input v-model="form.name" class="field mt-2" required><span v-if="form.errors.name" class="lp-error">{{form.errors.name}}</span></label><label class="lp-label">Description<textarea v-model="form.description" class="field mt-2 min-h-28"></textarea><span v-if="form.errors.description" class="lp-error">{{form.errors.description}}</span></label><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">Project type<input v-model="form.event_type" class="field mt-2"></label><label class="lp-label">Project date<input v-model="form.event_date" type="date" class="field mt-2"></label><label class="lp-label">Location<input v-model="form.location" class="field mt-2"></label><label class="lp-label">Membership status<select v-model="form.membership_status" class="field mt-2"><option value="open">Open</option><option value="closed">Closed</option></select></label></div><label class="flex gap-3 text-sm"><input v-model="form.is_active" type="checkbox" class="accent-indigo">Group is active</label></template>
<template v-else-if="section==='privacy'"><h2 class="text-xl font-bold">Privacy Settings</h2><label class="lp-label">Visibility<select v-model="form.privacy" class="field mt-2"><option value="private">Private</option><option value="link_only">Invitation only</option><option value="public">Public</option></select></label><label class="lp-label">Anonymous gallery access<select v-model="form.anonymous_access_mode" class="field mt-2"><option value="disabled">Disabled</option><option value="face_only">My Photos only</option><option value="full">Full gallery</option></select><span v-if="form.errors.anonymous_access_mode" class="lp-error">{{form.errors.anonymous_access_mode}}</span></label><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">Invitation expiry<input v-model="form.invitation_expires_at" type="datetime-local" class="field mt-2"><span v-if="form.errors.invitation_expires_at" class="lp-error">{{form.errors.invitation_expires_at}}</span></label><label class="lp-label">Join-code expiry<input v-model="form.event_code_expires_at" type="datetime-local" class="field mt-2"><span v-if="form.errors.event_code_expires_at" class="lp-error">{{form.errors.event_code_expires_at}}</span></label></div><label class="flex gap-3 text-sm"><input v-model="form.anyone_with_link_can_join" type="checkbox" class="accent-indigo">Allow joining through an authorized link</label><label class="flex gap-3 text-sm"><input v-model="form.allow_guest_upload" type="checkbox" class="accent-indigo">Allow participant uploads</label><label class="flex gap-3 text-sm"><input v-model="form.participants_can_edit_identity" type="checkbox" class="accent-indigo">Participants may edit their display identity</label><label class="flex gap-3 text-sm"><input v-model="form.face_recognition_enabled" type="checkbox" class="accent-indigo">Enable consent-led My Photos</label></template>
<template v-else-if="section==='downloads'"><h2 class="text-xl font-bold">View & Download</h2><label class="flex gap-3 text-sm"><input v-model="form.downloads_enabled" type="checkbox" class="accent-indigo">Allow authorized photo downloads</label><label class="flex gap-3 text-sm"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Apply watermark to supported delivery variants</label></template>
<template v-else><h2 class="text-xl font-bold">Branding & Sponsors</h2><p class="lp-subtitle">The backend supports a Group watermark. Sponsor records are not implemented and are not represented as working controls.</p><label class="flex gap-3 text-sm"><input v-model="form.watermark_enabled" type="checkbox" class="accent-indigo">Enable Group watermark</label><label class="lp-label">Watermark text<input v-model="form.watermark_text" class="field mt-2" maxlength="255"></label></template>
<UiAlert v-if="Object.keys(form.errors).length" tone="error">Review the highlighted Group settings.</UiAlert><UiButton type="submit" :loading="form.processing">Save Group Settings</UiButton></form><UiModal :open="confirmRemove" title="Remove Group cover?" description="The private original and all generated variants will be scheduled for safe cleanup." @close="confirmRemove=false" @confirm="removeCover"/>
</UiCard></div></div></AppShell></template>
